package com.aadil.ecommerce.dtos;import jakarta.validation.constraints.*;import lombok.Data;@Datapublic class UserRequestDTO {    @NotBlank(message = "Name must not be BLANK")    private String name;    @Email(message = "Email must be formatted in lowercase")    @NotBlank(message = "Email must not be NULL")    private String email;    @NotBlank(message = "Password must not be BLANK")    @Size(min = 8, max = 12, message = "Password must be at least 8 to 12 characters ")    @Pattern(regexp = "^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{8,}$")    private String password;}